--- GenerateAllCardProgressionEntity
--- 生成所有CardProgressEntity
---@return CardProgressionEntity[]
function CardProgressionUtils.GenerateAllEntity()
    ---@type CardProgressionMgr
    local cardProgressionMgr = CardProgressionMgr:GetInstance()
    ---@type CardComponent
    local cardComp           = cardProgressionMgr:GetCardComp()
    ---@type IllustratedHandbookComponent
    local illustratedHandbookComp = GameUtils.GetEntityCompByType(ECSComponentType.Constants.IllustratedHandbookComponent)
    local cardHandbookCollectDojo = illustratedHandbookComp:GetHandbookCollectDojo(Constants.HandbookCollectionType.ROLE)
    local allEntity               = {}
    local maxCardCount, cardCount = 0, 0
    local generateEntity = CardProgressionUtils.GenerateEntityByCardDojo
    local tInsert = table.insert
    for cardId, _ in pairs(cardHandbookCollectDojo.totalMap) do
        -- add total num
        maxCardCount = maxCardCount + 1
        -- add owned num
        local playerCardId = cardComp:GetIdByCardId(cardId)
        if playerCardId ~= nil then
            cardCount = cardCount + 1
            ---@type CardDojo
            local cardDojo = cardComp:GetCardById(playerCardId)
            tInsert(allEntity, generateEntity(cardDojo))
        end
        
    end
    
    return allEntity, cardCount, maxCardCount

end

function CardProgressionUtils.GenerateAllEntityByIds(ids)
    local entityList = {}

    local tInsert        = table.insert
    local generateEntity = CardProgressionUtils.GenerateEntityByCardDojo
    
    ---@type CardProgressionMgr
    local cardProgressionMgr = CardProgressionMgr:GetInstance()
    ---@type CardComponent
    local cardComp           = cardProgressionMgr:GetCardComp()
    for i, playerCardId in ipairs(ids) do
        ---@type CardDojo
        local cardDojo = cardComp:GetCardById(playerCardId)
        ---@type CardVo
        local cardVo   = cardConfMgr:GetCardByRefId(cardDojo.cardId)
        if cardVo.isHandbook then
            tInsert(entityList, generateEntity(cardDojo))
        end
    end
    return entityList
end

