--- GetFirstSortTypeData
--- 获取第一个排序类型数据
---@param sortType Constants.UISortType
function CardProgressionUtils.GetFirstSortTypeData(sortType)
    local row = CfUtils.GetCfLine(AutoIds.IdSetting1019, sortType)
    local types = parse_strings(parse_string(row, "type"))
    local sortTypeData
    for i, sortTypeId in ipairs(types) do
        row = CfUtils.GetCfLine(AutoIds.IdSetting1020, sortTypeId)
        local asc = parse_number(row, "condition") <= 0
        local typeDesc = parse_string(row, "typedesc")
        local conditionType = parse_number(row, "type")
        sortTypeData = {sortTypeId = checkNumber(sortTypeId), asc = asc, typeDesc = typeDesc, conditionType = conditionType, UIType = sortType}
        break

    end

    return sortTypeData

end

