--- CalcUpgradeLevelExp
--- 计算升级经验
---@param cardDojo CardDojo
---@param expAddition number
---@param initRare Constants.RareType
---@param maxLevel number
function CardProgressionUtils.CalcUpgradeLevelExp(cardDojo, expAddition, initRare, maxLevel)
    local originLevel      = checkNumber(cardDojo.cardLevel)
    local cardOriginExp    = checkNumber(cardDojo.cardExp)
    local curExpInfo       = cardConfMgr:GetCardExp(originLevel, initRare, maxLevel)
    local curLevelTotalExp = checkNumber(curExpInfo.totalExp)
    local feedingTotalExp  = cardOriginExp + expAddition
    local deltaExp         = feedingTotalExp - curLevelTotalExp
    
    local curLvNextLvExpInfo = cardConfMgr:GetCardExp(originLevel + 1, initRare, maxLevel)
    local newLevelNextLvExp  = curLvNextLvExpInfo.exp
    local newLevel           = originLevel
    local progressOrigin     = 0
    local progress           = 0
    local maxLevelTotalExp   = 0 
    if expAddition > 0 then
        ---吃完食物后的总经验
        local maxLevelExpConf  = cardConfMgr:GetCardExp(maxLevel, initRare, maxLevel)
        maxLevelTotalExp = maxLevelExpConf.totalExp
        local isMaxExp         = feedingTotalExp >= maxLevelTotalExp

        ---检查经验是否超过当前最大等级的经验
        if isMaxExp then
            progress = 1
            newLevel = maxLevel
            deltaExp = feedingTotalExp - maxLevelTotalExp
            newLevelNextLvExp = "---"
        else
            newLevel = BinarySearchLeftBound(newLevel, maxLevel, feedingTotalExp, function(middle)
                return cardConfMgr:GetCardExp(middle, initRare, maxLevel).totalExp
            end)
            
            local newLevelTotalExp = cardConfMgr:GetCardExp(newLevel, initRare, maxLevel).totalExp
            newLevelNextLvExp      = cardConfMgr:GetCardExp(newLevel + 1, initRare, maxLevel).exp
            deltaExp               = feedingTotalExp - newLevelTotalExp
            progress               = deltaExp / newLevelNextLvExp
        end

        --- 如果等级变化 则不显示原始经验条
        progressOrigin = originLevel ~= newLevel and 0 or ((cardOriginExp - curLevelTotalExp) / curLvNextLvExpInfo.exp)

    elseif maxLevel == originLevel then
        progressOrigin = 1
    else
        --- 当前等级下一等级经验配置 
        progressOrigin = ((cardOriginExp - curLevelTotalExp) / curLvNextLvExpInfo.exp)
    end

    return progressOrigin, progress, newLevel, deltaExp, newLevelNextLvExp, feedingTotalExp
end

