---@param envPath CardProgressionConstants.EnvPath
---@param targetNode UnityEngine.RectTransform
function CardProgressionUtils.ShowTips(prefabPath, envPath, targetNode, isCenter, param1, param2, param3)
    ResourceModule.LoadGameObjectAsync(prefabPath, function(go)
        if not isNull(go) and not isNull(targetNode) then
            local env = CfUtils.GetLuaScr(go, envPath)
