--- SortEntryBySortType
---@param entityList CardProgressionEntity[]
---@param sortType Constants.SortType
---@param asc boolean 是否是升序
function CardProgressionUtils.SortEntryBySortType(entityList, sortType, asc)
    -- 主界面看板娘 战斗力、稀有度、等级、星级、角色id、获得顺序排序
    local SortType = Constants.SortType
    local fieldNames
    if sortType == SortType.CombatPower then
        fieldNames = {"signboard", "combatPower", "rare", "cardLevel", "totalStar", "cardId", "id"}
    elseif sortType == SortType.Rare then
        fieldNames = {"signboard", "rare", "combatPower", "cardLevel", "totalStar", "cardId", "id"}
    elseif sortType == SortType.Level then
        fieldNames = {"signboard", "cardLevel", "rare", "combatPower", "totalStar", "cardId", "id"}
    elseif sortType == SortType.Star then
        fieldNames = {"signboard", "totalStar", "rare", "combatPower", "cardLevel", "cardId", "id"}
    elseif sortType == SortType.ConfId then
        fieldNames = {"signboard", "cardId", "rare", "combatPower", "cardLevel", "totalStar", "id"}
    elseif sortType == SortType.Birthday then
        fieldNames = {"signboard", "id", "rare", "combatPower", "cardLevel", "totalStar", "cardId"}
    elseif sortType == SortType.InitRare then
        fieldNames = {"signboard", "initRare", "combatPower", "rare", "cardLevel", "totalStar", "cardId", "id"}
    end

    if fieldNames then
        ---@type CardProgressionCombatEffUtils
        local CardProgressionCombatEffUtils     = import("Game.CardProgression.CardProgressionCombatEffUtils")
        local attrProvider2AttrAddId2V = CardProgressionCombatEffUtils.GenerateAllLimitlessGlobalProperty()

        local providerCombatEff2AddTypeConfig = CardProgressionCombatEffUtils.CalcAllLimitlessGlobalCombat()
        ---@type PlayerComponent
        local component          = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
        local signboardId        = checkNumber(component:GetPlayerDojo().signboardId)
        ---@param a CardProgressionEntity
        ---@param b CardProgressionEntity
        table.sort(entityList, function(a, b)
            a:InitSortField(signboardId, attrProvider2AttrAddId2V, providerCombatEff2AddTypeConfig)
            b:InitSortField(signboardId, attrProvider2AttrAddId2V, providerCombatEff2AddTypeConfig)
            return CommonChecker(a, b, fieldNames, asc, {
                ["signboard"] = true
            })
        end)
    end
    return entityList
end

function CardProgressionUtils.ScreenCards(cards, screenDic)
    local t       = {}
    local clone   = clone
    local tInsert = table.insert
    ---@param v CardProgressionEntity
    table.walk(cards, function(k, v)
        local cloneV
        --- CardProgressionEntity 没必要 clone
        if v.isEntity then
            v:InitFilterField()
            cloneV = v
        else
            ---@type CardDojo
            cloneV = clone(v)
            local refId          = cloneV.cardId or cloneV.goodsId or cloneV.refId
            ---@type CardVo
            local vo             = cardConfMgr:GetCardByRefId(refId)
            if isNull(vo) then printError(string.format('the setting id is null [%s]', tostring(refId))) end
            cloneV.rare          = v:GetRare()
            cloneV.totalStar     = checkNumber(v.star) + checkNumber(v.superStar)
            cloneV.attributeType = vo.attributeType
            cloneV.race          = vo.race
            cloneV.career        = vo.career
        end
        tInsert(t, cloneV)
    end)
    if not next(screenDic) then
        return t
    end
    local list = {}
    local CardFilterType = Constants.CardFilterType
    local typeConfig = {
        [CardFilterType.Quality]   = "rare",
        [CardFilterType.Star]      = "totalStar",
        [CardFilterType.Attribute] = "attributeType",
        [CardFilterType.Race]      = "race",
        [CardFilterType.Career]    = "career",
    }
    local indexOf = table.indexof
    for i, v in pairs(t) do
        local result = true
        for screenType, screenList in pairs(screenDic) do
            local name = typeConfig[screenType]
            result = result and indexOf(screenList, checkNumber(v[name])) ~= false
        end
        if result then
            tInsert(list, v)
        end
    end
    return list
end

--- GetRoleControllerEnv
---@return CardProgressionControllerRole
function CardProgressionUtils.GetRoleControllerEnv()
    local goName = CardProgressionConstants.SceneDefine.RoleController
    ---@type UnityEngine.GameObject
    local go = GameObject.Find(goName)

    local isInit = isNull(go)
    if isInit then
        go = GameUtils.LoadBundleAsync(CardProgressionConstants.PrefabPath.CardProgressionControllerRole)
        if not isNull(go) then
            go.name = goName
        end
    end
    
    ---@type CardProgressionControllerRole
    local env = CfUtils.GetLuaScr(go, CardProgressionConstants.EnvPath.CardProgressionControllerRole)
    return env
end

---PlayStarUpTimeline
---播放升星timeline
---@param skinId number 皮肤id
---@param timeLineName string timeLine名称
---@param localData table 升星成功所需数据
function CardProgressionUtils.PlayStarUpTimeline(skinId, timeLineName, localData)
    Events.Broadcast(CardProgressionConstants.EventNames.SetCultivateMainShowState, false)
    local isEmpty = string.isEmpty(timeLineName)
    if isEmpty then
        CardProgressionUtils.OpenDialog(Constants.UITypeIds.CardProgressionStarUpSuccess, localData)
        return
    end
    local timeLineName = "CardUpgrade_101_star"
    KTool.SetActive(UINavigationBarRoot.Instance.gameObject, false)
    return CardProgressionUtils.BlockerAndStartCo(timeLineName, function ()
        local subEnvPath = CardProgressionConstants.EnvPath.SimpleTimelineLoaderController
        local timelinePath = string.format(CardProgressionConstants.PrefabPath.CultivateTransitionPath, timeLineName)
        ---@type CardProgressionControllerRole
        local env = CardProgressionUtils.GetRoleControllerEnv()

        ---@type CardDojo
        local dojo = localData.dojo
        ---@type RolesVo
        local roleVo = cardConfMgr:GetRolesVoByCatId(dojo.cardId)
        local catId = roleVo.catId

        local animName2Loader = {
            ["action02_10102"]  = ResourceModule.LoadBundleAsync(string.format(CardProgressionConstants.AssetPath.Action02AnimPath, catId), nil, true),
            ["action03_10102"]  = ResourceModule.LoadBundleAsync(string.format(CardProgressionConstants.AssetPath.Action03AnimPath, catId), nil, true),
        }

        env:LoadRole(skinId, true, nil, true, dojo)
        env:LoadCat(skinId, nil, true)
        while not env:IsLoadRoleComplete() do
            cs_coroutine.yield_return()
        end
        
        while not env:IsLoadCatComplete() do
            cs_coroutine.yield_return()
        end

        local catGo        = env:GetCatBySkinId(skinId)
        local roleGo       = env:GetRoleBySkinId(skinId)
        local catGoTrans   = catGo.transform
        local roleGoTrans  = roleGo.transform
        local catGoParent  = catGoTrans.parent
        local roleGoParent = roleGoTrans.parent
        local params = {
            isShowUICamera = true,
            trackName2TrackInfo = {
                ["cat_ani"]       = {trackObject = catGo,  parentPath = "cat_loc"},
                ["cat_act"]       = {trackObject = catGo,  parentPath = "cat_loc"},
                ["character_act"] = {trackObject = roleGo, parentPath = "character_loc"},
            },
            timelineLoaderCompleteCb = function (tlGo, director)
                local animName2Clip ={}
                for key, loader in pairs(animName2Loader) do
                    animName2Clip[key] = CardProgressionUtils.CustomInstantiate(loader, nil, tlGo)
                end

                CardProgressionUtils.FillTimelineAnimClip(director, "cat_ani", animName2Clip)
               
            end,
            timeLinePlayCompleteCb = function ()
                catGoTrans:SetParent(catGoParent)
                KTool.SetLayer(roleGoParent.gameObject, roleGo, true)
                KTool.ResetLocalTransform(catGoTrans)
                
                roleGoTrans:SetParent(roleGoParent)
                KTool.SetLayer(catGoParent.gameObject, catGo, true)
                KTool.ResetLocalTransform(roleGoTrans)
                
                KTool.SetActive(roleGo, true)
                KTool.SetActive(catGo, true)
            end
        }
        
        local CriWareUtils        = import('Game.Entry.CriWareUtilsFix')
        CriWareUtils.PlaySe(UISheets.SFX_UI_SE.path, UISheets.SFX_UI_SE.ui_se_card_up_star_TL)

        local timelineParent = env:GetCultivateLocation().gameObject
        local co = UICommonUtils.ShowCommonSkipButton(subEnvPath, timelinePath, timelineParent, params)
        if co then
            cs_coroutine.yield_return(co)
        end

        CriWareUtils.Stop(UISheets.SFX_UI_SE.path, UISheets.SFX_UI_SE.ui_se_card_up_star_TL)

        KTool.SetActive(UINavigationBarRoot.Instance.gameObject, true)
        URPCameraController.Instance:SetActive(true)
        CardProgressionUtils.OpenDialog(Constants.UITypeIds.CardProgressionStarUpSuccess, localData)
        
    end)

end

---PlayAdvanceLevelUpURTimeline
