---FillTimelineAnimClip
---填充timeline动画片段
---@param director UnityEngine.Playables.PlayableDirector
---@param trackName string
---@param animName2Clip table<string, UnityEngine.AnimationClip>
function CardProgressionUtils.FillTimelineAnimClip(director, trackName, animName2Clip)
    ---@type GachaponUtils
    local gachaponUtils = import('Game.Gachapon.GachaponUtils')
    ---@param clip UnityEngine.Timeline.TimelineClip
    gachaponUtils.EachTimelineAnimationClips(director, trackName, function (clip)
        local asset = clip.asset
        if isNull(asset) then return end
        local realClip = animName2Clip[clip.displayName]
        if isNull(realClip) then return end
        asset.clip = realClip
    end)
end

