--- Instantiate
--- 通过loader 实例化 对象
---@param loader Engine.Modules.AbstractResourceLoader
---@param parent UnityEngine.GameObject
---@param retainGo UnityEngine.GameObject 此参数参入的话 loader的引用计数将随着 retainGo 的销毁而减少
---@param name   string
---@param customYieldFunc fun()
---@return UnityEngine.Object | UnityEngine.GameObject
function CardProgressionUtils.CustomInstantiate(loader, parent, retainGo, name, customYieldFunc)
    local isNull = isNull
    if isNull(loader) then
        return
    end

    local hasRetainGo = not isNull(retainGo)
    local hasParent = not isNull(parent)
    while not loader.IsCompleted do
        if customYieldFunc then
            customYieldFunc()
        else
            cs_coroutine.yield_return()
        end
    end

    local go
    if loader.IsSuccess then
        ---(原先有parent并且现在还有parent 或者 原先无parent) 并且 (原先有用于retain的对象并且未被销毁 或者 无原先有用于retain的对象)
        if ((hasParent and not isNull(parent)) or not hasParent) and 
            (hasRetainGo and isNotNull(retainGo) or not hasRetainGo) 
        then
            if isNull(retainGo) then
                go = loader:Instantiate()
            else
                go = loader.ResultObject
                if not isNull(go) then
                    loader:Retain(retainGo)
                end
            end

            if not isNull(go) and not isNull(parent) then
                if name then
                    go.name = name
                end
                KTool.SetParent(go, parent.gameObject, false)
            end
        end
       
    end

    loader:Release()

    return go
end

function CardProgressionUtils.CompareDojoAttributes(dojo, oldParams)
    local attributes = {}
    local tInsert    = table.insert
    local viewType   = CardProgressionConstants.AttrNodeType.Double
    FormulaUtils.CompareBasicAttrs(dojo, dojo, function (basicVo, preAttrV, attrV, index)
        if preAttrV ~= attrV then
            local isConversion = basicVo.isConversion
            tInsert(attributes, {
                icon         = basicVo.icon,
                name         = basicVo.name,
                attrNum      = attribute_format(isConversion, preAttrV),
                plusAttrNum  = attribute_format(isConversion, attrV),
                viewType     = viewType
            })
        end
    end, oldParams)
    return attributes
end

function CardProgressionUtils.EnabledParticleSystemsEmission(particleSystems, enabled)
    if not isNull(particleSystems) then
        for i = 0, particleSystems.Length - 1 do
            ---@type UnityEngine.ParticleSystem
            local ps = particleSystems[i]
            if not isNull(ps) then
                ps.emission.enabled = enabled
                if enabled then
                    ps:Play(true)
                end
            end
        end
    end
end

function CardProgressionUtils.IsTween()
    return DOTween.TotalPlayingTweens() > 0
end


---RegRoleSwipeRegion
---注册人物旋转
---关于为什么给没个页面都注册
---由于 养成主界面（order 0） 为了优化 batch 丢到了 场景中 如果使用 PinchAndDragInputModule 会导致子界面（order -1）点不了
---为什么 不把子界面 设置为0 
---为了优化 batch 丢到了 场景中  设置为0 导致tips 如果order 是0的话 会在 子界面下面
---为什么 PinchAndDragInputModule 实现 而不用 easy touch 
---因为 easy touch 3d 或 ui  的判断是全局的 不想修正easy touch 罢了   
---@param parent Engine.Modules.LuaBehaviour
---@param customCondition function
function CardProgressionUtils.RegRoleSwipeRegion(parent, customCondition)
    if isNull(parent) then
        return
    end
    local RoleSwipeRegion = parent.transform:Find("RoleSwipeRegion").gameObject:GetComponent(typeof(CS.Engine.UI.PinchAndDragInputModule))
    if isNull(RoleSwipeRegion) then
        return
    end
    KTool.SetActive(RoleSwipeRegion.gameObject, true)
    local abs = math.abs
    RoleSwipeRegion.onSingleFingerDrag:AddListener(function(delta)
        if customCondition and customCondition() == false then
            return
        end
        if CardProgressionUtils.IsTween() then
            return
        end
        local y = delta.y
        local x = delta.x
        local absX = abs(x)
        local absY = abs(y)
        if abs(absX - absY) <= 2 then
            return
        end

        ---左右滑动旋转
        if absY <= absX then
            local direction = x < 0 and 1 or -1
            Events.Broadcast(CardProgressionConstants.EventNames.RotationRole, direction * abs(x))
            return
        end
        
    end)
end

---CheckIsCanAdvanceLevelUp
---@param cardLevel number 卡牌等级
---@param advanceLevel number 进阶等级
function CardProgressionUtils.CheckIsCanAdvanceLevelUp(cardLevel, advanceLevel)
    local maxAdvanceLevel = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.MaxAdvanceLevel))
    local maxLevel        = cardConfMgr:GetCardMaxLevel(advanceLevel)
    local isCanAdvanceLevelUp = cardLevel >= maxLevel and advanceLevel < maxAdvanceLevel
    return isCanAdvanceLevelUp
end

