---CheckJumpCultivateMain
---跳转养成主界面相关检查
---@param params CardProgressionConstants.MainViewType
---@param extraPara table {[1] = cardId: option , cardId = option, playCardId = option}
function CardProgressionUtils.CheckJumpCultivateMain(params, extraPara)
    local parameter, errStr = nil, nil
    local mainViewType             = checkNumber(params) <= 0 and CardProgressionConstants.MainViewType.Intelligence or checkNumber(params)
    local MainViewConfig           = CardProgressionConstants.MainViewConfig
    local systemTogId              = MainViewConfig[mainViewType].systemToggleId
    local isLock                   = not GameUtils.IsUnlockedBySystemTogId(systemTogId)
    if isLock then
        errStr = GameUtils.GetUnlockDescrBySystemTogId(systemTogId)
        return parameter, errStr
    end

    ---无所需附加参数 
    if extraPara == nil or next(extraPara) == nil or type(extraPara) ~= "table" then
        parameter = { mainViewType = mainViewType}
        return parameter, errStr
    end
    --- 1. 如果是专武需要检查下是否有专武
    ---@type CardComponent
    local cardComp    = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardId      = checkNumber(extraPara[1] or extraPara.cardId)
    local playCardId  = checkNumber(extraPara.playCardId)
    ---@type CardDojo
    local dojo        = nil
    if cardId > 0 then
        playCardId = cardComp:GetIdByCardId(cardId) == nil and 0 or checkNumber(cardComp:GetIdByCardId(cardId))
        dojo = cardComp:GetCardById(playCardId)
    elseif playCardId > 0 then
        dojo   = cardComp:GetCardById(playCardId)
        cardId = dojo.cardId
    end
    if dojo == nil then
        ---@type CardVo
        local cardVo = cardConfMgr:GetCardByRefId(cardId)
        errStr = localize("未获得_nam_", {_name_ = cardVo.name})
        return parameter, errStr
    end

    if CardProgressionConstants.MainViewType.ExclusiveWeapon == mainViewType then
        local ids = cardConfMgr:GetRoleCardExclusiveWeaponIds(cardId)
        if ids == nil then
            errStr = localize("未满足专武解锁条件")
            return parameter, errStr
        end
    end
    parameter = { mainViewType = mainViewType, playerCardId = playCardId, isSingle = 1}
    return parameter, errStr
end

---CheckJumpFavor
---跳转好感度相关检查
---@param params table
---@param extraPara table {[1] = cardId: option , cardId = option, playCardId = option}
function CardProgressionUtils.CheckJumpFavor(params, extraPara)
    local parameter, errStr = nil, nil
    ---@type CardComponent
    local cardComp    = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
    local cardId      = checkNumber(extraPara[1] or extraPara.cardId)
    local playCardId  = checkNumber(extraPara.playCardId)
    if cardId > 0 then
        playCardId = cardComp:GetIdByCardId(cardId) == nil and 0 or checkNumber(cardComp:GetIdByCardId(cardId))
    end
    if playCardId == nil or playCardId == 0 then
        ---@type CardVo
        local cardVo = cardConfMgr:GetCardByRefId(cardId)
        errStr = localize("未获得_nam_", {_name_ = cardVo.name})
        return parameter, errStr
    end

    local cardDojo = cardComp:GetCardById(playCardId)
    parameter = {playerCardId = playCardId, cardId = cardId, favorLevel = checkNumber(cardDojo.favorabilityLevel), viewType = CardProgressionConstants.IntroductionViewType.Favor}

    return parameter, errStr
end


---Toast
---养成用tips提示
---@param point integer 战斗力变化
---@param rTimeLength number
function CardProgressionUtils.ChangePointToast(point, rTimeLength)
    -- 战斗力无变化时不显示
    if checkInt(point) == 0 then
        return 
    end
    
    if isNull(rTimeLength) then
        rTimeLength = 2
    end
    local parent = GameUtils.GetUITopCanvas()
    if parent == nil then
        parent = UIModule.RootCanvas.transform
    end
    local go = poolManager:GetNew("Prefabs/CultivateOversea/CultivateOverseaTipsPanel.prefab", true, 1)
    if not isNull(go) then
        KTool.SetActive(go, true)
        if not KTool.IsNull(UIModule.RootCanvas.gameObject) then
            local t = go:GetComponent(typeof(RectTransform))
            t:SetParent(parent)
            t.anchorMin = Vector2.zero
            t.anchorMax = Vector2.one
            t.offsetMin = Vector2.zero
            t.offsetMax = Vector2.zero
            t.localPosition = Vector3.zero
            t.localRotation = Quaternion.identity
            t.localScale = Vector3.one
            go.layer = parent.gameObject.layer

            ---获取lua脚本然后执行方
            ---@type Engine.Modules.LuaBehaviour
            local uiAutoTips = GetLuaBehaviour(go, "Game.CardProgression.Common.CardProgressionAutoTips")
            if not KTool.IsNull(uiAutoTips) then
                uiAutoTips.Env:ShowHUD(point, rTimeLength)
            end
        end
    end
end

