function CardProgressionUtils.GetCultivateListRedPoint()
    local t = {
        -- { CardProgressionUtils.GetCanStarUpCardNum, Constants.SystemToggleIds.Id104 },
        { CardProgressionUtils.IsCanReceiveFavorReward, Constants.SystemToggleIds.Id109, true        },
        { CardProgressionUtils.GetShowNewSkinCardNum,   Constants.SystemToggleIds.Id107, false, true },
    }
    
    local num = 0
    for i, config in ipairs(t) do
        local func, systemToggleId, extraPara, isNotDependedCard = SafeUnpack(config)
        local isUnlock  = GameUtils.IsUnlockedBySystemTogId(systemToggleId)
        if isUnlock and type(func) == "function" then
            if isNotDependedCard then
                if func(extraPara) then
                    num = 1
                end
            else
                ---@type CardComponent
                local cardComp  = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                local cardDojos = cardComp:GetAllCardTable()
                for index, cardDojo in ipairs(cardDojos) do
                    if func(cardDojo, extraPara) then
                        num = 1
                        break
                    end
                end
            end
            if num > 0 then
                return num
            end
        end
    end
    return num
end

function CardProgressionUtils.IsCanShowEntryCardHeadRedPoint(cardDojo)
    local t = {
        CardProgressionUtils.IsCanStarUp,
        CardProgressionUtils.IsCanReceiveFavorReward,
        CardProgressionUtils.IsCanShowSkinNewByDojo,
    }
    for index, func in pairs(t) do
        if func(cardDojo) then
            return true
        end
    end
    return false
end

