function CardProgressionUtils.IsCanShowSkinNewByDojo(cardDojo)
    local cardSkins = CardConfMgr:GetInstance():GetCardSkinsByCardId(cardDojo.cardId)
    if cardSkins == nil then return false end
    for _, skinId in ipairs(cardSkins) do
