---@param cardDojo CardDojo
function CardProgressionUtils.IsCanStarUp(cardDojo, isIgnore)
    if not isIgnore and not GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id104) then
        return false
    end
    if not cardDojo then return false end
    
    local cardId = cardDojo.cardId
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    --- 不存在卡牌表 或者 不显示在图鉴中
    if not cardVo or not cardVo.isHandbook then return false end
    
    local star      = checkNumber(cardDojo.star)
    local superStar = checkNumber(cardDojo.superStar)
    local realStar  = star + superStar
    local maxStar   = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.MaxStar))
    if realStar >= maxStar then
         return false
    end
    
    --- 获取到下一星级所需消耗
    ---@type CardStarVo
    local starVo   = cardConfMgr:GetCardStarInfo(cardId, realStar + 1)
    local consumes = starVo:GetConsumes()
    if consumes == nil then return false end
    
    local res = nil
    --- 检查材料是否满足
    for i, v in ipairs(consumes) do
        local isSatisfy = GoodsUtils.GetThingNo(v.goodsId) >= v.goodsNum
        if res == nil then
            res = isSatisfy
        else
            res = res and isSatisfy
        end
    end
    return res == true
end

