---IsCanReceiveFavorReward
---@param cardDojo CardDojo
---@param isIgnore boolean
function CardProgressionUtils.IsCanReceiveFavorReward(cardDojo, isIgnore)
    if not isIgnore and not GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id104) then
        return false
    end
    local originLevel       = checkNumber(cardDojo.favorabilityLevel)
    local receivedLevel2Res = cardDojo:GetFavorLv2ReceivedRes()
    local ids               = cardConfMgr:GetFavorableExpRewardIdGroup(cardDojo.cardId)
    for i, id in ipairs(ids) do
        ---@type FavorableExpRewardVo
        local vo      = cardConfMgr:GetFavorableExpRewardVo(id)
        if vo.level > 1 and originLevel >= vo.level and receivedLevel2Res[vo.level] == nil then
            return true
        end
    end
    return false
end

---IsCanReceiveStoryReward
---是否能领取剧情奖励
---@param cardDojo CardDojo
---@param isIgnore boolean
function CardProgressionUtils.IsCanReceiveStoryReward(cardDojo, isIgnore)
    if cardDojo == nil then return false end
    
    if not isIgnore and not GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id110) then
        return false
    end

    local favorLevel = checkNumber(cardDojo.favorabilityLevel)
    local cardId     = checkNumber(cardDojo.cardId)
    local receivedLevel2Res = cardDojo:GetStoryId2ReceivedRes()
    local ids        = cardConfMgr:GetFavorableExpRewardIdGroup(cardId)
    for i, id in ipairs(ids) do
        ---@type FavorableExpRewardVo
        local vo      = cardConfMgr:GetFavorableExpRewardVo(id)
        local fileId  = vo.file
        if fileId > 0 and favorLevel >= vo.level and receivedLevel2Res[fileId] ~= true then
            return true
        end
    end

    return false
end

--- GetCardLevelLimit
--- 获取卡牌等级限制
function CardProgressionUtils.GetCardLevelLimit(customLevel)
    local playerLevel     = customLevel or CardProgressionUtils.GetPlayerLevel()
    ---@type CardLevelLimitVo[]
    local vos             = cardConfMgr:GetAllCardLevelLimitVo()
    local leftId, rightId = 1, #vos
    local targetId = BinarySearchLeftBound(leftId, rightId, playerLevel, function(middle)
        return vos[middle].playerLevel
    end)
    ---@type CardLevelLimitVo
    local vo = vos[targetId]
    if vo then
        return vo.levelLimit, vo.Id    
    end
    
    return 0, 0
    
end

function CardProgressionUtils.GetCardLevelLimitData(id)
    ---@type CardLevelLimitVo
    local vo = cardConfMgr:GetCardLevelLimitVo(id)
    return vo.playerLevel, vo.levelLimit
end

function CardProgressionUtils.GetPlayerLevel()
    ---@type PlayerComponent
    local playerComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.PlayerComponent)
    ---@type PlayerDojo
    local playerDojo      = playerComponent.playerDojo
    local playerLevel     = checkNumber(playerDojo.level)
    return playerLevel
end

function CardProgressionUtils.CalcFashionQuickUpLvConsume(skinId, nextLv, maxLv)
    local goodsId2LeftNum = {}
    local goodsId2ConsumeNum = {}
    local targetLv = 0
    local goBackIndex
    for i = nextLv, maxLv, 1 do
        ---@type SkinAttributeVo
        local skinAttrVo = cardConfMgr:GetSkinAttributeVo(skinId, i)
        local upLevelConsumes = skinAttrVo:GetConsumes()
        for index, value in ipairs(upLevelConsumes) do
            local goodsId = value.goodsId
            if goodsId2LeftNum[goodsId] == nil then
                goodsId2LeftNum[goodsId] = GoodsUtils.GetThingNo(goodsId)
            end
            local num             = goodsId2LeftNum[goodsId]
            local consume = (goodsId2ConsumeNum[goodsId] or 0) + value.goodsNum
            if num < consume then
                goBackIndex = index
                break
            end
            goodsId2ConsumeNum[goodsId] = consume
        end
        
        if goBackIndex and goBackIndex >= 1 then
            targetLv = i - 1
            for idx = 1, goBackIndex - 1, 1 do
                local consumeData = upLevelConsumes[idx]
                local goodsId = consumeData.goodsId
                ---减去多加的
                goodsId2ConsumeNum[goodsId] = goodsId2ConsumeNum[goodsId] - consumeData.goodsNum
            end
            break
        else
            targetLv = i
        end
    end
    return goodsId2ConsumeNum, targetLv
end

---CollectFavorLevelRewards
---@param data table
---@param cardId number 卡牌id
function CardProgressionUtils.CollectFavorLevelRewards(data, cardId, isUpLevel)
    ---@type FavorableExpRewardVo
    local vo = data.vo
        
    -----@type CardVo
    local cardVo = cardConfMgr:GetCardByRefId(cardId)
    
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local function GetPhotoPathById(goodsId)
        ---@type GoodsVo
        local goodsVo = goodsConfMgr:GetGoodsVoById(goodsId)
        return goodsVo.photoPath, goodsVo
    end

    local t = {}
    if not isUpLevel and next(vo.rewards) ~= nil then
        local reward = table.takeFirst(vo.rewards)
        local photoIcon, goodsVo = GetPhotoPathById(reward.goodsId)
        table.insert(t, {icon = photoIcon, text = string.format("%s X%s", goodsVo.name, reward.goodsNum)})
    end

    if cardVo and checkNumber(cardVo.mainCat) > 0 then
        if checkNumber(vo.level) == checkNumber(cardVo.mainCat) then
            local photoIcon, _ = GetPhotoPathById(5340004)
            table.insert(t, {icon = photoIcon, text = localize("解锁功能【切换猫形态】")})
        end
    end
    if not string.isEmpty(vo.voice) then
        local goodsId = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.RoleVoiceId))
        local photoIcon = GetPhotoPathById(goodsId)
        ---@type RoleVoiceVo
        local voiceVo = RoleVoiceMgr:GetInstance():GetRoleVoiceVoById(vo.voice)
        table.insert(t, {icon = photoIcon, text = localize("解锁【_name_】语音", {_name_ = voiceVo.name})})
    end
    
    if not string.isEmpty(vo.action) then
        table.insert(t, {icon = "", text = localize("解锁【_name_】动作 ", {_name_ = vo.action_txt})})
        
    end

    if vo.file > 0 then
        local goodsId = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.RoleFileId))
        local photoIcon = GetPhotoPathById(goodsId)
        table.insert(t, {icon = photoIcon, text = localize("解锁【个人档案_name_】", {_name_ = vo.file})})
    end
    
    if not isUpLevel and not string.isEmpty(vo.property) then
        local CardAttributes = import("Game.Setting.Vo.CardAttributes")
        ---@type CardAttributes
        local attr = CardAttributes.New()
        attr:FillVoByPropertyStr(vo.property)

        local attrAddId2V = attr.attrs
        --local attrList = {}
        local goodsId = checkNumber(cardConfMgr:GetCardProgressionParamsById(CardProgressionConstants.Params.RoleAttrId))
        local photoIcon = GetPhotoPathById(goodsId)
        for attrAddId, attrV in pairs(attrAddId2V) do
            ---@type AttrDefinesVo
            local attrDefinesVo = cardConfMgr:GetBasicAttrByBasicAttrAdditionId(attrAddId)
            local text = attribute_format(vo.isConversion, checkNumber(attrV))
            table.insert(t, {icon = photoIcon, text = attrDefinesVo.name .. '+' .. text})
        end
        
    end

    if checkNumber(vo.mood) > 0 then
        local photoIcon, _ = GetPhotoPathById(5340005)
        table.insert(t, {icon = photoIcon, text = localize("心情值上限提升至_num_", {_num_ = checkNumber(vo.mood)})})
    end

    return t
end

function CardProgressionUtils.GenerateSkinAttrTypeData(attrAddId2V, attrAddIdInfo, maxLvAttrAddIdInfo, isMax, isAddPlus)
    local t = {}
    for attrAddId, attrV in pairs(attrAddId2V) do
        ---@type AttrDefinesVo
        local vo = cardConfMgr:GetBasicAttrByBasicAttrAdditionId(attrAddId)
        local text = attribute_format(vo.isConversion, checkNumber(attrV))
        local isEffective = attrAddIdInfo ~= nil and attrAddIdInfo[attrAddId] == true
        local attrStatus = isEffective and 2 or 1
        table.insert(t, {
            attrAddId = attrAddId,
            isConversion = vo.isConversion,
            order = vo.order,
            icon = vo.icon,
            name = vo.name,
            attrStatus = attrStatus,
            attrNum = isAddPlus and '+' .. text or text,
            maxFlag = maxLvAttrAddIdInfo ~= nil and maxLvAttrAddIdInfo[attrAddId] == true,
            viewType = CardProgressionConstants.AttrNodeType.Single,
        })
    end
    table.sort(t, function(a, b) return a.order < b.order end)
    return t
end

return CardProgressionUtils